    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(src), len(src[0])
    counts = {}
    for row in src:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    marker = min((v for v in counts if v != 0), key=lambda v: counts[v])
    cells = [(r, c) for r in range(h) for c in range(w) if src[r][c] == marker]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    shape = [(r-r0, c-c0) for r, c in cells]
    mh, mw = r1-r0+1, c1-c0+1
    for r in range(h-mh+1):
        for c in range(w-mw+1):
            if all(src[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = marker
    return out
